void ScriptSession::clearPlayerOrders(std::uint32_t handle) {queuedPlayerUnits_.erase(handle);if(auto found=units_.find(handle);found!=units_.end())found->second->playerOrders.clear();}
bool ScriptSession::queuePlayerOrder(std::uint32_t handle,const PlayerCommand& command) {auto found=units_.find(handle);if(found==units_.end() || found->second->playerOrders.size()>=32)return false;auto next=command;next.units={handle};next.queued=false;found->second->playerOrders.push_back(std::move(next));queuedPlayerUnits_.insert(handle);return true;}
